    '''
    N: an integer
    M: an integer
    edges: a list of tuples of integers
    '''
    parent = list(range(N+1))
    rank = [0] * (N+1)

    def find(x):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x!= root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    for x, y in edges:
        union(x, y)

    return len(set(find(i) for i in range(1, N+1)))
